"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["17128"],{25283(e){e.exports=JSON.parse('{"id":"FIN-493","slug":"statistical-significance","term":"Statistical Significance","also_known_as":[],"difficulty":"Intermediate","definition":"Statistical significance describes a result that is unlikely to have occurred by chance alone if there were no real effect, usually judged by whether its p-value falls below a chosen threshold, such as 0.05.","explanation":["When researchers find a difference or relationship in data, they need to know whether it reflects something real or just random variation. A result is called statistically significant when the probability of seeing it, assuming no real effect, is low enough.","For example, if an analysis finds that companies with a certain characteristic earned higher returns, with a p-value of 0.01, the result would be considered statistically significant at the 5% level, and also at the 1% level.","Statistical significance is not the same as practical importance. With very large data sets, tiny effects can be statistically significant but too small to matter. A trading strategy that beats the market by 0.01% a year might be statistically significant but would be wiped out by trading costs. Conversely, an important effect might not reach statistical significance in a small sample.","Significance can also be misleading if many different tests are run, because some will appear significant purely by chance. This problem, sometimes called data mining or p-hacking, is a particular concern in investment research, where many strategies can be tested on the same historical data."],"note":"","total":1500,"prev":{"slug":"stationarity","term":"Stationarity"},"next":{"slug":"statutory-accounts","term":"Statutory Accounts"}}')}}]);